def retire_non_jss_reallocations(apps, schema_editor):
    """Banding is Junior-Secondary-only now (configuration 0009 switched it
    off for SS-1/2/3, which defaulted ON before). Any proposal those classes
    already had in flight would otherwise still auto-apply at the next term
    start (apply_due_reallocations) and reshuffle students across what are
    now manually-assigned subject streams. Supersede them, and clear the
    next_class_arm preview a RELEASED one already showed students/parents."""
    ClassReallocation = apps.get_model("academics", "ClassReallocation")
    Student = apps.get_model("academics", "Student")

    stale = ClassReallocation.objects.filter(status__in=["pending", "released"]).exclude(
        school_class__category="junior_secondary",
    )
    released_ids = list(stale.filter(status="released").values_list("id", flat=True))
    if released_ids:
        Student.objects.filter(
            reallocation_moves__reallocation_id__in=released_ids, next_class_arm__isnull=False,
        ).update(next_class_arm=None)
    stale.update(status="superseded")


